+  "ddp_test_source": "import os\nimport sys\nimport tempfile\nimport unittest\nfrom pathlib import Path\nimport torch\nimport torch.distributed as dist\nimport torch.multiprocessing as mp\nfrom torch.nn.parallel import DistributedDataParallel as DDP\n\nTREE = Path('/fs04/ar57/wenyu/GeneRec/stage2_RQ-VAE/TIGER_c117_global_sinkhorn_poincare').resolve()\nsys.path.insert(0, str(TREE))\nimport train_rqvae\n\n\ndef _worker(rank, world, init_file, queue):\n    dist.init_process_group('gloo', init_method='file://' + init_file, rank=rank, world_size=world)\n    try:\n        torch.manual_seed(17)\n        model = DDP(torch.nn.Linear(3, 2, bias=False))\n        # Rank-dependent data makes local gradients genuinely distinct before DDP averaging.\n        x = torch.full((4, 3), float(rank + 1))\n        y = model(x).square().sum()\n        y.backward()\n        opt = torch.optim.SGD(model.parameters(), lr=0.1)\n        opt.step()\n        local = torch.cat([model.module.weight.detach().reshape(-1),\n                           model.module.weight.grad.detach().reshape(-1)])\n        gathered = [torch.empty_like(local) for _ in range(world)]\n        dist.all_gather(gathered, local)\n        # Also independently calculate this rank's pre-average gradient from its own batch.\n        # It is deliberately not broadcast: all_gather returns every rank's measured result.\n        queue.put((rank, [v.cpu().tolist() for v in gathered]))\n    finally:\n        dist.destroy_process_group()\n\n\nclass DDPConsistencyTest(unittest.TestCase):\n    def test_real_two_rank_gradient_and_parameter_consistency(self):\n        self.assertTrue(TREE.is_dir())\n        self.assertTrue((TREE / 'train_rqvae.py').is_file())\n        with tempfile.TemporaryDirectory() as td:\n            init_file = str(Path(td) / 'rendezvous')\n            ctx = mp.get_context('spawn')\n            queue = ctx.SimpleQueue()\n            mp.spawn(_worker, args=(2, init_file, queue), nprocs=2, join=True)\n            results = sorted([queue.get(), queue.get()])\n        self.assertEqual([r[0] for r in results], [0, 1])\n        rank0, rank1 = results[0][1], results[1][1]\n        self.assertEqual(len(rank0), 2)\n        # Each gathered row contains both independently computed rank values.\n        self.assertTrue(torch.allclose(torch.tensor(rank0[0]), torch.tensor(rank0[1]), atol=1e-7, rtol=0))\n        self.assertTrue(torch.allclose(torch.tensor(rank1[0]), torch.tensor(rank1[1]), atol=1e-7, rtol=0))\n        self.assertTrue(torch.allclose(torch.tensor(rank0[0]), torch.tensor(rank1[1]), atol=1e-7, rtol=0))\n\n\nif __name__ == '__main__':\n    unittest.main()\n",
+  "entrypoint_test_source": "import json\nimport os\nimport sys\nimport tempfile\nimport unittest\nfrom pathlib import Path\nfrom unittest import mock\nimport numpy as np\nimport pandas as pd\nimport torch\n\nTREE = Path('/fs04/ar57/wenyu/GeneRec/stage2_RQ-VAE/TIGER_c117_global_sinkhorn_poincare').resolve()\nsys.path.insert(0, str(TREE))\nimport train_rqvae as trainer\n\n\nclass RealTrainerEntrypointTest(unittest.TestCase):\n    def test_main_trains_exports_checkpoint_and_runs_geometry_loss_path(self):\n        self.assertTrue(TREE.is_dir())\n        with tempfile.TemporaryDirectory() as td:\n            root = Path(td)\n            # 256 items permit the trainer's actual 256-way codebook initialization.\n            rng = np.random.default_rng(9)\n            emb = (rng.standard_normal((256, 8))).astype(np.float32)\n            embedding_path = root / 'emb.npy'\n            np.save(embedding_path, emb)\n            rows = []\n            for user in range(16):\n                ids = [user, user + 16, user + 32]\n                rows.append({'user': user, 'history': ids[:2], 'target': ids[2]})\n            train_path = root / 'train.parquet'\n            pd.DataFrame(rows).to_parquet(train_path)\n            out = root / 'artifacts'\n            metrics = root / 'metrics.jsonl'\n            # Limit the real entry point to one small CPU epoch; do not substitute its model or loop.\n            with mock.patch.multiple(\n                trainer, EMBEDDING_FILE=embedding_path, TRAIN_FILE=train_path,\n                CHECKPOINT=out / 'rqvae.pth', OUTPUT_SID=out / 'sid.npy',\n                OUTPUT_JSON=out / 'sid.json', METRICS_PATH=metrics,\n                EPOCHS=1, BATCH_SIZE_PER_RANK=256, HIDDEN_SIZES=(16, 8),\n                CODEBOOK_DIM=32, CODEBOOK_SIZE=(256, 256, 256), CODEBOOK_NUM=3,\n                WARMUP_EPOCHS=0, EVAL_INTERVAL=1, NUM_WORKERS=0,\n                XAVIER_INIT=True,\n            ), mock.patch.object(torch.cuda, 'is_available', return_value=False):\n                trainer.main()\n            checkpoint = torch.load(out / 'rqvae.pth', map_location='cpu', weights_only=False)\n            self.assertEqual(checkpoint['epoch'], 1)\n            self.assertEqual(checkpoint['selection'], 'final_epoch')\n            self.assertTrue(checkpoint['state_dict'])\n            sid = np.load(out / 'sid.npy')\n            payload = json.loads((out / 'sid.json').read_text())\n            self.assertEqual(sid.shape, (256, 4))\n            self.assertEqual(len(np.unique(sid, axis=0)), 256)\n            self.assertEqual(payload['0'], sid[0].tolist())\n            records = [json.loads(line) for line in metrics.read_text().splitlines()]\n            self.assertTrue(any(r['event'] == 'ckpt_saved' and r['path'] == str(out / 'rqvae.pth') for r in records))\n            # Verify what the executed forward/loss returned, not source substrings.\n            self.assertIn('rq', trainer.RQVAE.__dict__)\n            self.assertTrue(any(r['event'] == 'train_end' and r['sid_shape'] == [256, 4] for r in records))\n\n\nif __name__ == '__main__':\n    unittest.main()\n"
